#!/usr/bin/env pwsh
$basedir=Split-Path $MyInvocation.MyCommand.Definition -Parent

$exe=""
$pathsep=":"
$env_node_path=$env:NODE_PATH
$new_node_path="E:\私有项目\learn-anything-main\node_modules\.pnpm\@commitlint+cli@21.0.2_@typ_d1b6feb3a41bbaa02a397150e357965c\node_modules\@commitlint\cli\node_modules;E:\私有项目\learn-anything-main\node_modules\.pnpm\@commitlint+cli@21.0.2_@typ_d1b6feb3a41bbaa02a397150e357965c\node_modules;E:\私有项目\learn-anything-main\node_modules\.pnpm\node_modules"
if ($PSVersionTable.PSVersion -lt "6.0" -or $IsWindows) {
  # Fix case when both the Windows and Linux builds of Node
  # are installed in the same directory
  $exe=".exe"
  $pathsep=";"
} else {
  $new_node_path="/mnt/e/私有项目/learn-anything-main/node_modules/.pnpm/@commitlint+cli@21.0.2_@typ_d1b6feb3a41bbaa02a397150e357965c/node_modules/@commitlint/cli/node_modules:/mnt/e/私有项目/learn-anything-main/node_modules/.pnpm/@commitlint+cli@21.0.2_@typ_d1b6feb3a41bbaa02a397150e357965c/node_modules:/mnt/e/私有项目/learn-anything-main/node_modules/.pnpm/node_modules"
}
if ([string]::IsNullOrEmpty($env_node_path)) {
  $env:NODE_PATH=$new_node_path
} else {
  $env:NODE_PATH="$new_node_path$pathsep$env_node_path"
}

$ret=0
if (Test-Path "$basedir/node$exe") {
  # Support pipeline input
  if ($MyInvocation.ExpectingInput) {
    $input | & "$basedir/node$exe"  "$basedir/../@commitlint/cli/cli.js" $args
  } else {
    & "$basedir/node$exe"  "$basedir/../@commitlint/cli/cli.js" $args
  }
  $ret=$LASTEXITCODE
} else {
  # Support pipeline input
  if ($MyInvocation.ExpectingInput) {
    $input | & "node$exe"  "$basedir/../@commitlint/cli/cli.js" $args
  } else {
    & "node$exe"  "$basedir/../@commitlint/cli/cli.js" $args
  }
  $ret=$LASTEXITCODE
}
$env:NODE_PATH=$env_node_path
exit $ret
